      return { ok: okA, message: okA ? "" : "got " + fmt(ca.data.length > 24 ? ca.data.slice(0, 24) + "…" : ca.data) + " · expected " + fmt(cb.data.length > 24 ? cb.data.slice(0, 24) + "…" : cb.data) };
