          if (!thrown) {
            r.passed = false;
            r.actual = "no exception";
            r.expected = String(t.expected || "an error");
            r.message = "expected an exception, but the code ran without throwing";
          } else {
            var want = String(t.expected || "");
            r.actual = String((thrown && thrown.message) || thrown);
            r.passed = want === "" || r.actual.toLowerCase().indexOf(want.toLowerCase()) >= 0;
            r.expected = want === "" ? "any error" : want;
            if (!r.passed) r.message = "error message does not contain " + JSON.stringify(want);
          }
