// ── worker glue ──────────────────────────────────────────────────────────────

const TFJS_VERSION = "4.22.0";
const TFJS_LOCAL = "/vendor/tfjs/tf.min.js"; // vendored same-origin (offline-friendly)
const TFJS_CDN = "https://cdn.jsdelivr.net/npm/@tensorflow/tfjs@" + TFJS_VERSION + "/dist/tf.min.js";

let booted = false;
let bootError = null;
const sandboxStore = {};   // persistent notebook cell state
const dataCache = new Map();

function post(msg) {
  self.postMessage(msg);
}

async function boot() {
  post({ id: "kernel", type: "status", status: "booting", detail: "Loading TensorFlow.js…" });
  try {
    // vendored same-origin copy first (fast, no third-party dependency) …
    try {
      importScripts(TFJS_LOCAL);
    } catch (e) {
      // … fall back to the CDN if the vendored bundle is missing
      post({ id: "kernel", type: "status", status: "booting", detail: "Vendored tf.js missing — falling back to CDN…" });
      importScripts(TFJS_CDN);
    }
    await tf.setBackend("cpu"); // deterministic + no OffscreenCanvas requirement
    await tf.ready();
    booted = true;
    post({
      id: "kernel",
      type: "status",
      status: "ready",
      detail: "TensorFlow.js " + tf.version.tfjs + " · " + tf.getBackend() + " backend",
    });
  } catch (e) {
    bootError = String(e);
    post({ id: "kernel", type: "error", message: "TFJS kernel failed to boot: " + bootError });
  }
}

async function ensureBoot() {
  if (!booted && !bootError) await boot();
  if (bootError) throw new Error("kernel not booted: " + bootError);
}

async function loadData(name) {
  if (dataCache.has(name)) return dataCache.get(name);
  const res = await fetch("/tfdata/" + name + ".json");
  if (!res.ok) throw new Error("loadData: unknown dataset '" + name + "' (HTTP " + res.status + ")");
  const data = await res.json();
  dataCache.set(name, data);
  return data;
}

async function handleRun(msg) {
  await ensureBoot();
  const payload = await PyLabJsHarness.runCell(tf, msg.code, {
    loadData: loadData,
    store: sandboxStore,
  });
  post({ id: msg.id, type: "run-result", payload });
}

async function handleTest(msg) {
  await ensureBoot();
  const payload = await PyLabJsHarness.runExercise(tf, msg.userCode, msg.exercise, {
    loadData: loadData,
  });
  post({ id: msg.id, type: "test-result", payload });
}

self.onmessage = async (event) => {
  const msg = event.data;
  try {
    switch (msg.type) {
      case "init":
        await boot();
        break;
      case "loadPackages":
        // TF.js ships inside the worker — nothing to load; ack as ready.
        await ensureBoot();
        post({ id: "kernel", type: "status", status: "ready", detail: "TensorFlow.js ready" });
        break;
      case "run":
        await handleRun(msg);
        break;
      case "test":
        await handleTest(msg);
        break;
      case "reset":
        await ensureBoot();
        for (const k of Object.keys(sandboxStore)) delete sandboxStore[k];
        dataCache.clear();
        post({ id: "kernel", type: "status", status: "ready", detail: "kernel memory cleared" });
        break;
      default:
        post({ id: msg.id, type: "error", message: "unknown message type" });
    }
  } catch (e) {
    post({ id: msg.id || "kernel", type: "error", message: String((e && e.message) || e) });
  }
};
